int n=0;void Check(bool ok,string text){if(!ok)throw new Exception(text);n++;Console.WriteLine("PASS: "+text);}void Reject(Action a,string name){try{a();}catch(ArgumentException){Check(true,name);return;}catch(System.IO.InvalidDataException){Check(true,name);return;}throw new Exception("Accepted invalid: "+name);}
const int w=200,h=100;var data=Enumerable.Repeat((byte)255,w*h*4).ToArray();void Fill(PixelRect r,byte R,byte G,byte B){for(int y=r.Y;y<r.Bottom;y++)for(int x=r.X;x<r.Right;x++){int p=(y*w+x)*4;data[p]=B;data[p+1]=G;data[p+2]=R;}}
Fill(new(24,34,40,22),220,40,40);Fill(new(77,40,6,10),0,0,0);var original=data.ToArray();var region=new PixelRect(20,30,70,30);RecoveryPatch Build(Annotation a,EditorDocument d)=>BackgroundRecovery.Build(data,w,h,new(0,0,w,h),a.Mockup!.SourceBounds,a.Mockup.Background,a.Mockup.Type,[]);
