var a=MockupStudio.Create(region,new(0,0,w,h),new("#FFFFFF","#DC2828","#FFFFFF",1));a.Mockup!.Type=MockupKind.Button;a.Text="Tìm";var doc=new EditorDocument{OriginalWidth=w,OriginalHeight=h,Annotations=[a]};doc.Validate(w,h,"");var session=new EditorSession(doc){BeforeCommit=(before,d)=>BackgroundRecovery.Finalize(before,d,Build)};string first=doc.Serialize();session.Change(d=>d.Annotations[0].Translate(80,0));Check(session.Document.Recoveries.Count==1&&session.Document.Version==20,"First move creates persistent independent background recovery");Check(session.Document.Recoveries[0].Bounds==region&&session.Document.Annotations[0].Mockup is {EraseOriginal:false,RecoveryId:not null},"Recovery stays at original location, while body moves separately");string moved=session.Document.Serialize();session.Change(d=>d.Annotations[0].Mockup!.Background="#000000");Check(session.Document.Recoveries[0].Background=="#FFFFFF","Body backdrop changes cannot recolor old-location background");session.Undo();session.Undo();Check(session.Document.Serialize()==first,"Undo move restores exact pre-mask document");session.Redo();Check(session.Document.Serialize()==moved,"Redo move restores body and independent mask");session.Change(d=>d.Annotations.Clear());Check(session.Document.Annotations.Count==0&&session.Document.Recoveries.Count==1&&session.Document.HasEdits,"Deleting element retains old-location recovery instead of revealing original button");string deleted=session.Document.Serialize();session.Undo();Check(session.Document.Serialize()==moved,"Undo deletion restores element without removing recovery");session.Redo();Check(session.Document.Serialize()==deleted,"Redo deletion is exact");var loaded=EditorDocument.Deserialize(deleted);Check(loaded.RecoveryHistory.Any(x=>x.Action=="Di chuyển")&&loaded.RecoveryHistory.Any(x=>x.Action=="Xóa"),"Operation journal persists move/delete history with the document");loaded.Validate(w,h,"");Check(loaded.Recoveries[0].Mask==patch.Mask,"Save/reopen retains deleted-element mask independently");session.Undo();var current=session.Document;var copy=current.Snapshot();copy.Recoveries[0].Background="#000000";copy.Recoveries[0].Protected.Add(new(20,30,2,2));Check(current.Recoveries[0].Background=="#FFFFFF"&&current.Recoveries[0].Protected.Count==0,"Autosave snapshot owns independent mask metadata");var packet=AnnotationClipboard.Copy(current,current.Annotations.Select(x=>x.Id));var pasted=new EditorDocument{OriginalWidth=w,OriginalHeight=h};AnnotationClipboard.Paste(pasted,packet,2,x=>new(x.Left,x.Top,x.Width,x.Height));pasted.Validate(w,h,"");Check(pasted.Recoveries.Count==0&&pasted.Annotations[0].Mockup is {RecoveryId:null,EraseOriginal:false},"Copy/paste cannot copy old-image recovery or leave dangling reference");var duplicated=AnnotationEditing.Duplicate(current,current.Annotations.Select(x=>x.Id).ToArray(),x=>new(x.Left,x.Top,x.Width,x.Height));Check(current.Annotations.Single(x=>duplicated.Contains(x.Id)).Mockup!.RecoveryId==null&&current.Recoveries.Count==1,"Duplicate has its own body and no second source erasure");
var invalid=patch.Copy();invalid.Mask="AQ";Reject(()=>invalid.Validate(w,h),"Corrupt base64 mask rejected");invalid=patch.Copy();invalid.Bounds=new(int.MaxValue,0,20,20);Reject(()=>invalid.Validate(w,h),"Overflowing source bounds rejected");invalid=patch.Copy();invalid.Mask="";Reject(()=>invalid.Validate(w,h),"Mask dimension mismatch rejected");var flat=BackgroundRecovery.Build(data,w,h,new(0,0,w,h),region,"#000000",MockupKind.Button,[]);Check(flat.NeedsReview,"Incompatible background color requests review instead of claiming reliable recovery");
var workflow=new CaptureWorkflowSettings();Check(!workflow.RequireEnter,"Photo capture defaults to release-to-capture");Check(workflow.Hotkeys.Where(x=>x.Enabled).All(x=>x.Action is PhotoAction.Region or PhotoAction.Display or PhotoAction.Repeat),"Retired Current/Window/Element shortcuts are disabled");var defaults=ToolShortcutCatalog.Merge([],workflow.Hotkeys);EditorShortcutRules.Validate(defaults,workflow.Hotkeys);Check(defaults.Where(x=>x.Enabled).Select(x=>(x.Modifiers,x.Key)).Distinct().Count()==defaults.Count(x=>x.Enabled),"Default editor shortcuts are unique and compatible with capture");Check(ToolShortcutCatalog.All.Any(x=>x.Command=="Studio:Recovery")&&ToolShortcutCatalog.All.Any(x=>x.Command=="Studio:Mockup"),"Every More feature, including Mockup/Recovery, is configurable");var changed=defaults.Select(x=>x.Command=="Tool:Callout"?x with{Enabled=true,Modifiers=0,Key=0x52}:x).ToList();Reject(()=>EditorShortcutRules.Validate(changed,workflow.Hotkeys),"Duplicate single-key binding rejected");changed=defaults.Select(x=>x.Command=="Tool:Callout"?x with{Enabled=true,Modifiers=6,Key=0x35}:x).ToList();Reject(()=>EditorShortcutRules.Validate(changed,workflow.Hotkeys),"Editor/capture shortcut collision rejected");changed=defaults.Select(x=>x.Command=="Tool:Callout"?x with{Enabled=true,Modifiers=2,Key=0x53}:x).ToList();Reject(()=>EditorShortcutRules.Validate(changed,workflow.Hotkeys),"Core save command cannot be shadowed");changed=defaults.Select(x=>x.Command=="Studio:Recovery"?x with{Enabled=true,Modifiers=3,Key=0x39}:x).ToList();EditorShortcutRules.Validate(changed,workflow.Hotkeys);Check(true,"Custom modifier chord can launch a More tool");workflow.RequireEnter=true;workflow.EditorHotkeys=changed;CaptureWorkflowStore.Validate(workflow);var reopened=JsonSerializer.Deserialize<CaptureWorkflowSettings>(JsonSerializer.Serialize(workflow))!;Check(reopened.RequireEnter&&reopened.EditorHotkeys.Single(x=>x.Command=="Studio:Recovery").Key==0x39,"Confirmation setting and custom shortcuts roundtrip together");var folder=Path.Combine(Path.GetTempPath(),"cvx-m3-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{CaptureWorkflowStore.Save(folder,workflow);var history=CaptureWorkflowStore.Load(folder,out var warning);Check(warning==null&&history.EditorHotkeys.Count==changed.Count,"Saved workflow reload retains all tool bindings");}finally{Directory.Delete(folder,true);}
